export const EXPLAIN: DialogueLine[] = [
  {"id": "p2-01", "who": 1, "write": null, "ms": {"kirill": 1567, "anton": 1515, "alexander": 1593, "ermil": 1411, "dasha": 1646, "lera": 1620, "masha": 1698, "julia": 1437, "jane": 1332}, "text": "Ну что, сверяемся?"},
  {"id": "p2-02", "who": 2, "write": null, "ms": {"kirill": 4989, "anton": 4571, "alexander": 4493, "ermil": 4441, "dasha": 4676, "lera": 4754, "masha": 4963, "julia": 4493, "jane": 4545}, "text": "Давай. Только сразу скажу я вообще не очень понял как тут равное искать."},
  {"id": "p2-03", "who": 2, "write": null, "ms": {"kirill": 7027, "anton": 6478, "alexander": 6426, "ermil": 6426, "dasha": 6609, "lera": 6713, "masha": 7105, "julia": 6374, "jane": 6661}, "text": "Одну пару сторон нашёл и всё. Остальные наискосок идут. Вроде похожи а может и нет."},
  {"id": "p2-04", "who": 2, "write": null, "ms": {"kirill": 3004, "anton": 2795, "alexander": 2873, "ermil": 2795, "dasha": 2795, "lera": 2900, "masha": 3030, "julia": 2743, "jane": 2873}, "text": "А как равные углы искать совсем не понимаю."},
  {"id": "p2-05", "who": 1, "write": null, "ms": {"kirill": 3527, "anton": 3474, "alexander": 3422, "ermil": 3474, "dasha": 3370, "lera": 3553, "masha": 3579, "julia": 3318, "jane": 3291}, "text": "Да, вижу. А-дэ равно бэ-цэ. Это правильно."},
  {"id": "p2-06", "who": 2, "write": null, "ms": {"kirill": 2011, "anton": 1724, "alexander": 1698, "ermil": 1620, "dasha": 1620, "lera": 1855, "masha": 1802, "julia": 1750, "jane": 1776}, "text": "Ого а у тебя сколько всего."},
  {"id": "p2-07", "who": 1, "write": null, "ms": {"kirill": 6687, "anton": 6191, "alexander": 6165, "ermil": 6113, "dasha": 6374, "lera": 6400, "masha": 6844, "julia": 6269, "jane": 6348}, "text": "Да тут не очень сложно давай быстро объясню. Нам ведь обоим нужно понимать. Спросить могут любого."},
  {"id": "p2-08", "who": 2, "write": null, "ms": {"kirill": 1855, "anton": 1907, "alexander": 1750, "ermil": 1724, "dasha": 1829, "lera": 1907, "masha": 1907, "julia": 1776, "jane": 1724}, "text": "Давай. Только не быстро."},
  {"id": "p2-09", "who": 1, "write": null, "ms": {"kirill": 3866, "anton": 3683, "alexander": 3709, "ermil": 3318, "dasha": 3918, "lera": 3866, "masha": 3997, "julia": 3736, "jane": 3396}, "text": "Хорошо не быстро. Смотри. ты помнишь теорему Пифаг+ора?"},
  {"id": "p2-10", "who": 2, "write": null, "ms": {"kirill": 4545, "anton": 4284, "alexander": 4284, "ermil": 4467, "dasha": 4493, "lera": 4650, "masha": 4833, "julia": 4049, "jane": 4441}, "text": "Ну так, не очень. Там как-то стороны треугольника между собой связаны."},
  {"id": "p2-11", "who": 1, "write": null, "ms": {"kirill": 7600, "anton": 6139, "alexander": 5721, "ermil": 6008, "dasha": 6165, "lera": 7391, "masha": 6504, "julia": 6973, "jane": 5590}, "text": "Да, прямоугольного… О, придумал проще! Помнишь первый признак равенства треугольников?"},
  {"id": "p2-12", "who": 2, "write": null, "ms": {"kirill": 3265, "anton": 3109, "alexander": 3109, "ermil": 3056, "dasha": 3161, "lera": 3265, "masha": 3396, "julia": 3030, "jane": 3161}, "text": "Конечно. По двум сторонам и углу между ними."},
  {"id": "p2-13", "who": 1, "write": null, "ms": {"kirill": 8934, "anton": 8046, "alexander": 8307, "ermil": 8411, "dasha": 8176, "lera": 8307, "masha": 8882, "julia": 7863, "jane": 8516}, "text": "Он самый. Теперь смотри на а-бэ и цэ-дэ. Давай вот такой треугольник построим к а-бэ и вот такой к цэ-дэ."},
  {"id": "p2-14", "who": 2, "write": null, "ms": {"kirill": 1280, "anton": 1202, "alexander": 1254, "ermil": 1123, "dasha": 1254, "lera": 1306, "masha": 1280, "julia": 888, "jane": 1149}, "text": "Ага, вижу."},
  {"id": "p2-15", "who": 1, "write": null, "ms": {"kirill": 3448, "anton": 3135, "alexander": 3187, "ermil": 3213, "dasha": 3265, "lera": 3370, "masha": 3579, "julia": 3788, "jane": 3291}, "text": "Вот эти стороны у них по четыре клетки а эти по две."},
  {"id": "p2-16", "who": 2, "write": null, "ms": {"kirill": 549, "anton": 522, "alexander": 522, "ermil": 470, "dasha": 575, "lera": 549, "masha": 575, "julia": 470, "jane": 522}, "text": "Да."},
  {"id": "p2-17", "who": 1, "write": null, "ms": {"kirill": 4702, "anton": 4362, "alexander": 4206, "ermil": 4545, "dasha": 4467, "lera": 4545, "masha": 4676, "julia": 4911, "jane": 4989}, "text": "А вот эти углы прямые по девяносто градусов. Значит равны между собой."},
  {"id": "p2-18", "who": 2, "write": null, "ms": {"kirill": 967, "anton": 914, "alexander": 967, "ermil": 888, "dasha": 914, "lera": 993, "masha": 1019, "julia": 940, "jane": 914}, "text": "Есть такое."},
  {"id": "p2-19", "who": 1, "write": null, "ms": {"kirill": 7967, "anton": 7262, "alexander": 7340, "ermil": 7314, "dasha": 7471, "lera": 7732, "masha": 8020, "julia": 7471, "jane": 7602}, "text": "Ну и всё. Значит треугольники равны и оставшиеся стороны у них тоже равны. То есть а-бэ равно цэ-дэ."},
  {"id": "p2-20", "who": 2, "write": null, "ms": {"kirill": 4153, "anton": 3736, "alexander": 3736, "ermil": 3631, "dasha": 3788, "lera": 4023, "masha": 3997, "julia": 3318, "jane": 3605}, "text": "Ага, точно. Крутяк! Так просто оказывается!"},
  {"id": "p2-21", "who": 1, "write": null, "ms": {"kirill": 7340, "anton": 6766, "alexander": 6975, "ermil": 6661, "dasha": 6949, "lera": 7053, "masha": 7471, "julia": 6713, "jane": 6870}, "text": "Да. А теперь такие же треугольники можно дорисовать к диагонали а-цэ. Вот один а вот второй."},
  {"id": "p2-22", "who": 2, "write": null, "ms": {"kirill": 470, "anton": 444, "alexander": 444, "ermil": 444, "dasha": 470, "lera": 470, "masha": 470, "julia": 418, "jane": 496}, "text": "Так."},
  {"id": "p2-23", "who": 1, "write": null, "ms": {"kirill": 3318, "anton": 3187, "alexander": 3239, "ermil": 3291, "dasha": 3109, "lera": 3396, "masha": 3422, "julia": 3318, "jane": 3344}, "text": "И то же самое. Получаем что а-о равно о-цэ."},
  {"id": "p2-24", "who": 2, "write": null, "ms": {"kirill": 5277, "anton": 4885, "alexander": 4833, "ermil": 4911, "dasha": 4963, "lera": 5172, "masha": 5460, "julia": 4859, "jane": 4989}, "text": "Гениально! Кажется я уловил идею. Так ведь и про вторую диагональ можно."},
  {"id": "p2-25", "who": 1, "write": null, "ms": {"kirill": 2560, "anton": 2429, "alexander": 2508, "ermil": 2403, "dasha": 2534, "lera": 2586, "masha": 2586, "julia": 2429, "jane": 2377}, "text": "Да, то же самое. Попробуй сам."},
  {"id": "p2-25f", "who": 1, "write": null, "ms": {"kirill": 2612, "anton": 2508, "alexander": 2508, "ermil": 2482, "dasha": 2560, "lera": 2638, "masha": 2664, "julia": 2456, "jane": 2429}, "text": "Да, то же самое. Попробуй сама."},
  {"id": "p2-26", "who": 2, "write": null, "ms": {"kirill": 8411, "anton": 7445, "alexander": 7497, "ermil": 7288, "dasha": 7549, "lera": 7889, "masha": 8150, "julia": 7236, "jane": 7732}, "text": "Так… дорисовываю треугольники. Эти стороны равны эти равны угол прямой. Значит бэ-о равно о-дэ."},
  {"id": "p2-27", "who": 1, "write": null, "ms": {"kirill": 4127, "anton": 3840, "alexander": 3866, "ermil": 3971, "dasha": 3918, "lera": 4075, "masha": 4101, "julia": 3840, "jane": 3944}, "text": "Да, всё правильно. Таким же образом можно и про углы."},
  {"id": "p2-28", "who": 2, "write": null, "ms": {"kirill": 967, "anton": 1019, "alexander": 993, "ermil": 940, "dasha": 1045, "lera": 1097, "masha": 1123, "julia": 1045, "jane": 940}, "text": "Это про какие?"},
  {"id": "p2-29", "who": 1, "write": null, "ms": {"kirill": 5512, "anton": 5172, "alexander": 5042, "ermil": 4911, "dasha": 5224, "lera": 5329, "masha": 5616, "julia": 5224, "jane": 5016}, "text": "Про противоположные. Что угол а равен углу цэ. Видишь одинаковые?"},
  {"id": "p2-30", "who": 2, "write": null, "ms": {"kirill": 4571, "anton": 4336, "alexander": 4310, "ermil": 4310, "dasha": 4362, "lera": 4493, "masha": 4650, "julia": 3579, "jane": 5153}, "text": "Да, похожи. Нет… не соображу какие треугольники взять."},
  {"id": "p2-31", "who": 1, "write": null, "ms": {"kirill": 4859, "anton": 4467, "alexander": 4519, "ermil": 4441, "dasha": 4571, "lera": 4519, "masha": 4885, "julia": 4336, "jane": 4519}, "text": "Смотри. Давай проведём эту высоту из бэ и эту из дэ."},
  {"id": "p2-32", "who": 2, "write": null, "ms": {"kirill": 627, "anton": 575, "alexander": 601, "ermil": 601, "dasha": 601, "lera": 653, "masha": 627, "julia": 601, "jane": 627}, "text": "Вижу."},
  {"id": "p2-33", "who": 1, "write": null, "ms": {"kirill": 2664, "anton": 2482, "alexander": 2560, "ermil": 2534, "dasha": 2586, "lera": 2612, "masha": 2717, "julia": 2482, "jane": 2638}, "text": "Теперь вот этот и вот этот треугольники."},
  {"id": "p2-34", "who": 2, "write": null, "ms": {"kirill": 6374, "anton": 5851, "alexander": 5747, "ermil": 5669, "dasha": 5878, "lera": 6113, "masha": 6296, "julia": 5669, "jane": 5904}, "text": "Точно! Снова две стороны и угол между ними. Значит угол а равен углу цэ."},
  {"id": "p2-35", "who": 1, "write": null, "ms": {"kirill": 5486, "anton": 5120, "alexander": 5120, "ermil": 5068, "dasha": 5120, "lera": 5433, "masha": 5773, "julia": 5616, "jane": 5251}, "text": "Да. Когда по клеткам считаешь это самый простой способ пристраивать такие треугольники."},
  {"id": "p2-36", "who": 2, "write": null, "ms": {"kirill": 3239, "anton": 2873, "alexander": 2847, "ermil": 2795, "dasha": 2978, "lera": 3135, "masha": 3187, "julia": 2900, "jane": 2821}, "text": "Спасибо классный способ! Теперь всё понятно."},
  {"id": "p2-37", "who": 2, "write": null, "ms": {"kirill": 7680, "anton": 7079, "alexander": 6975, "ermil": 7053, "dasha": 7236, "lera": 7523, "masha": 7889, "julia": 7053, "jane": 7602}, "text": "Здравствуйте Татьяна Алексеевна. Мне сначала вообще было непонятно. А сейчас объясняют и вроде ясно становится."},
  {"id": "p2-38", "who": 1, "write": null, "ms": {"kirill": 3892, "anton": 3709, "alexander": 3683, "ermil": 3840, "dasha": 3814, "lera": 3762, "masha": 4075, "julia": 3631, "jane": 3944}, "text": "Достраиваем треугольники по клеткам и смотрим первый признак."},
  {"id": "p2-39", "who": 2, "write": null, "ms": {"kirill": 2090, "anton": 1959, "alexander": 1959, "ermil": 2011, "dasha": 2038, "lera": 2142, "masha": 2142, "julia": 1829, "jane": 1881}, "text": "Так. На чём мы остановились?"},
  {"id": "p2-tq", "who": "T", "write": null, "ms": {"alena": 1620, "filipp": 1567}, "text": "Как вы тут? Как дела?"},
  {"id": "p2-tb", "who": "T", "write": null, "ms": {"alena": 2926, "filipp": 3056}, "text": "Отлично. Разбирайтесь, не буду мешать."},
];
